Use the active sheet as the answer sheet. Compute each subdivision’s earliest year, rank subdivisions by that year with first appearance as a deterministic tie-break, and write each row’s subdivision rank into C2:C22.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title
if sheet_name not in wb.sheetnames:
    ws = wb.create_sheet(sheet_name)
else:
    ws = wb[sheet_name]

vws = vals[sheet_name]
max_row = vws.max_row

earliest_year = {}
first_seen = {}

for r in range(2, max_row + 1):
    year = vws.cell(row=r, column=1).value
    sub = vws.cell(row=r, column=2).value

    if sub is None:
        continue
    sub = str(sub).strip()
    if not sub:
        continue

    if year is None:
        continue
    try:
        year_val = int(float(year))
    except (TypeError, ValueError):
        continue

    if sub not in first_seen:
        first_seen[sub] = r

    if sub not in earliest_year or year_val < earliest_year[sub]:
        earliest_year[sub] = year_val

ordered_subs = sorted(
    earliest_year.keys(),
    key=lambda s: (earliest_year[s], first_seen[s])
)

rank = {sub: i + 1 for i, sub in enumerate(ordered_subs)}

for r in range(2, max_row + 1):
    sub = vws.cell(row=r, column=2).value
    if sub is None:
        ws.cell(row=r, column=3).value = None
        continue
    sub = str(sub).strip()
    ws.cell(row=r, column=3).value = rank.get(sub)

wb.save(OUT)

print("sheet:", sheet_name)
print("rows:", max_row - 1)
print("subdivisions:", len(rank))
print("order:", ordered_subs)
print("first answers:", [ws.cell(row=r, column=3).value for r in range(2, 7)])
